/// The wording, per language.
///
/// One map rather than sixty-five files, deliberately. A translator's unit of work
/// here is one row of keys across languages — checking that `done` in Telugu does
/// not contradict `done` in Kannada, or that a long sentence did not get cut short
/// in translation — and that comparison is impossible when the languages live in
/// separate files. The cost is a large file; the alternative's cost is a translation
/// nobody can review.
///
/// `en` is the source text and the fallback for every key. It is also the only
/// entry a human wrote: every other language came from a machine, which the app
/// says out loud before anyone picks one. Adding a reviewed language means editing
/// its row here and clearing `machineTranslated` in `app_locales.dart` — nothing
/// else, and no code generation.
///
/// Keys are grouped in the order they are declared on `AppText`, so a key added
/// there and forgotten here is an English sentence in a translated screen rather
/// than a missing one. `tool/i18n_status.dart` prints exactly which keys each
/// language is missing, which is how that is caught rather than hoped for.
library;

