/// The keys whose wording carries `{hole}` markers, and the holes each one has.
///
/// A template is the one place a translation can be *present and wrong* rather
/// than missing: drop `{months}` and the sentence loses its number while still
/// reading as a sentence. `tool/i18n_status.dart` compares this list against
/// every locale, so a translation that invents or drops a hole fails the build
/// instead of shipping a sentence with the wrong shape.
const Map<String, List<String>> kTemplateKeys = {
  'cycleModeDetail': ['mode', 'contraception'],
  'storageUnreadable': ['error'],
  'databaseSize': ['kb'],
  'backupReady': ['kb'],
  'backupFailed': ['error'],
  'restoreFailed': ['error'],
  'ageDays': ['n'],
  'ageHours': ['n'],
  'restoreDone': ['age', 'kb'],
  'languageMachineTag': ['name'],
  'languageRowMachine': ['name'],
  'remindersQueryFailed': ['detail'],
  'daysBeforeMany': ['days'],
  'daysAfterMany': ['days'],
  'todayAt': ['time'],
  'tomorrowAt': ['time'],
  'reportReadyOne': ['months'],
  'reportReadyMany': ['days', 'months'],
  'reportFailed': ['error'],
  'annualReviewDueOn': ['when'],
  'annualReviewDueOverdue': ['when'],
  'privacyReadError': ['detail'],
  'privacyReceiptHeader': ['when'],
  'nextAt': ['when'],
  'onDayAt': ['day', 'time'],
  'summaryDaysValue': ['days'],
  'summaryRangeValue': ['short', 'long'],
