    'termsIntro': 'इस स्थिति का नाम 12 मई 2026 को बदला गया। इसके बारे में कुछ नहीं बदला — पर शब्द बदल गए, और कुछ साल तक दोनों तरह के नाम सुनने को मिलेंगे।',
    'termsWhy': 'पुराना नाम अंडाशय और पुटियों की ओर इशारा करता था। बदलाव के पीछे हुए एक अध्ययन में पाया गया कि इसमें अंडाशय की असामान्य पुटियाँ बढ़ती नहीं हैं, इसलिए वह नाम इस स्थिति के सबसे कम हिस्से का बखान करता था और मेटाबॉलिक तथा हार्मोनल पक्ष छोड़ देता था — जो असल में इसे ट्रैक करने लायक़ बनाता है। इसीलिए नाम बदला।',
    'termsTransition': 'यह बदलाव तीन साल में पूरा होगा और 2028 की अंतरराष्ट्रीय गाइडलाइन में पूरी तरह लागू होगा। ज़्यादातर डॉक्टर, लैब रिपोर्ट और अस्पताल के रिकॉर्ड अब भी PCOS कहते हैं, तो कुछ समय दोनों शब्द चाहिए होंगे।',
    'termsPcod': 'PCOD वह शब्द है जो दक्षिण एशिया में सबसे ज़्यादा लोग इस्तेमाल करते हैं, और जिसके साथ सबसे ज़्यादा खोजें आती हैं। नाम बदलने में इसका ज़िक्र नहीं था, और यह ऐप तय नहीं करता कि इसे इस्तेमाल करने वाले लोग एक ही बात कहते हैं — यह यहाँ इसलिए है क्योंकि अपने शब्दों में जवाब पाने के लिए पहले नए शब्द जानना ज़रूरी नहीं होना चाहिए।',
    'termsStance': 'यह ऐप निदान नहीं करता और यह भी तय नहीं करता कि कौन-सा नाम सही है। यह आपके दर्ज किए नंबर, और क्लिनिशियन जिन सीमाओं को देखते हैं उनके बग़ल में छापता है, और नाम तथा निदान आप दोनों पर छोड़ देता है।',
    'termsPmosExpansion': 'पॉलीएंडोक्राइन मेटाबॉलिक ओवेरियन सिंड्रोम',
    'termsPcosExpansion': 'पॉलीसिस्टिक ओवरी सिंड्रोम',
    'termsPcodExpansion': 'पॉलीसिस्टिक ओवेरियन डिज़ीज़',
