    'summarySinceLastLabel': 'पिछले पीरियड शुरू होने से अब तक',
    'summaryThresholdsNote': 'क्लिनिशियन आम तौर पर 21 से 35 दिन के चक्र को सामान्य सीमा मानते हैं, और एक साल में 8 से कम पीरियड शुरुआत को ध्यान देने लायक़। आपके नंबर इन आंकड़ों के बग़ल में छपे हैं। यह ऐप तय नहीं करता कि वे आप पर लागू होते हैं या नहीं।',
