    'termsHeading': 'Как называется это состояние',
    'termsIntro': 'Это состояние переименовали 12 мая 2026 года. В нём самом ничего не изменилось — изменились слова, и оба варианта вам будут встречаться ещё несколько лет.',
    'termsWhy': 'Старое название указывало на яичники и на кисты. Одно из исследований, стоящих за переименованием, показало, что числа аномальных кист яичников оно не увеличивает, поэтому название описывало самую малую часть и оставляло за бортом метаболическую и гормональную сторону — а именно она и делает состояние тем, за чем стоит следить. Поэтому его и изменили.',
    'termsTransition': 'Переход идёт три года и полностью завершится в международном руководстве 2028 года. Большинство врачей, лабораторных отчётов и больничных записей всё ещё говорят PCOS, так что какое-то время понадобятся оба слова.',
    'termsPcod': 'PCOD — термин, которым пользуется большинство в Южной Азии, и с ним приходит большинство поисковых запросов. В переименовании он не упомянут, и это приложение не решает, вкладывают ли в него тот же смысл те, кто им пользуется: он здесь потому, что для того, чтобы вас встретили на вашем языке, не нужно сначала выучить новый.',
    'termsStance': 'Это приложение не ставит диагноз и не решает, какое название верное. Оно печатает цифры, которые вы записали, рядом с порогами, которые проверяет врач, а название и диагноз оставляет вам двоим.',
